"""Native Docker context excludes credentials generated by release CI."""

from pathlib import Path
import subprocess


def test_cloudrun_context_excludes_github_actions_credentials(tmp_path):
    context = tmp_path / "context"
    output = tmp_path / "exported"
    context.mkdir()
    repository = Path(__file__).parents[2]
    (context / ".dockerignore").write_bytes((repository / ".dockerignore").read_bytes())
    (context / "Dockerfile").write_text("FROM scratch\nCOPY . /\n")
    (context / "application.txt").write_text("public application control")
    credentials = [Path("gha-creds-synthetic.json"), Path("nested/gha-creds-synthetic.json")]
    for name in credentials:
        path = context / name
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text('{"type":"synthetic-test-only","marker":"must-not-enter-image"}')

    # Export the real filtered filesystem without creating an image or container.
    result = subprocess.run(
        ["docker", "buildx", "build", "--file", str(context / "Dockerfile"),
         "--output", f"type=local,dest={output}", str(context)],
        capture_output=True, text=True, timeout=60, check=False,
    )
    assert result.returncode == 0, result.stdout + result.stderr
    assert (output / "application.txt").read_text() == "public application control"
    leaked = [str(name) for name in credentials if (output / name).exists()]
    assert leaked == [], f"Workflow credential files entered the native Docker context: {leaked}"
